CREATE TABLE IF NOT EXISTS pilot_rollout_profiles(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','READINESS_REVIEW','UAT_ACTIVE','PAUSED','CERTIFIED')),financial_autonomy INTEGER NOT NULL DEFAULT 0 CHECK(financial_autonomy=0),created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS pilot_rollout_properties(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,rollout_id TEXT NOT NULL,property_id TEXT NOT NULL,property_role TEXT NOT NULL CHECK(property_role IN('PRIMARY','COMPARISON')),pms_family TEXT NOT NULL CHECK(pms_family='OPERA_OHIP'),credential_scope TEXT NOT NULL CHECK(credential_scope='PROPERTY_ISOLATED'),readiness_status TEXT NOT NULL CHECK(readiness_status IN('IDENTITY_REQUIRED','CONFIGURATION_REQUIRED','UAT_READY','PAUSED')),external_actions_enabled INTEGER NOT NULL DEFAULT 0 CHECK(external_actions_enabled IN(0,1)),financial_autonomy INTEGER NOT NULL DEFAULT 0 CHECK(financial_autonomy=0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,rollout_id,property_id));
CREATE TABLE IF NOT EXISTS pilot_rollout_gates(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,rollout_id TEXT NOT NULL,property_id TEXT NOT NULL,gate_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('VERIFIED','CONFIGURATION_REQUIRED','RECOMMENDED','OUT_OF_SCOPE')),evidence_json TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,rollout_id,property_id,gate_key));
CREATE INDEX IF NOT EXISTS pilot_rollout_property_scope_idx ON pilot_rollout_properties(organization_id,rollout_id,property_id,readiness_status);
CREATE INDEX IF NOT EXISTS pilot_rollout_gate_scope_idx ON pilot_rollout_gates(organization_id,rollout_id,property_id,gate_key,status);
